$id = 0
function CallTool([string]$name, [string]$args = "{}") {
  $script:id++
  $h = @{ "Accept"="application/json, text/event-stream"; "MCP-Method"="tools/call"; "MCP-Protocol-Version"="2026-07-28"; "MCP-Name"=$name }
  $meta = '"_meta":{"io.modelcontextprotocol/protocolVersion":"2026-07-28","io.modelcontextprotocol/clientCapabilities":{}}'
  $body = '{"jsonrpc":"2.0","id":' + $script:id + ',"method":"tools/call","params":{"name":"' + $name + '","arguments":' + $args + ',' + $meta + '}}'
  $raw = (Invoke-WebRequest -Uri $url -Method Post -Headers $h -ContentType "application/json" -Body $body -TimeoutSec 180).Content
  foreach ($line in ($raw -split "`n")) { if ($line.StartsWith("data: ")) { return ($line.Substring(6) | ConvertFrom-Json -Depth 100).result } }
  return ($raw | ConvertFrom-Json -Depth 100).result
}
